package com.orchardskydigital.clogslots;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ClogSlotsConfig.GROUP)
public interface ClogSlotsConfig extends Config
{
	String GROUP = "clogslots";

	@Getter
	@RequiredArgsConstructor
	enum SlotSize
	{
		SMALL("Small", 1.0),
		MEDIUM("Medium", 1.5),
		LARGE("Large", 2.0);

		private final String label;
		private final double scale;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "slotSize",
		name = "Slot machine size",
		description = "How big the slot machine appears on screen",
		position = 1
	)
	default SlotSize slotSize()
	{
		return SlotSize.LARGE;
	}

	@ConfigItem(
		keyName = "spinSeconds",
		name = "Spin duration (s)",
		description = "How long the slot machine spins before landing",
		position = 2
	)
	default int spinSeconds()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "showGoalOverlay",
		name = "Show goal on screen",
		description = "Show your current goal on a plaque in the game view (drag it with Alt held to move it)",
		position = 3
	)
	default boolean showGoalOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "excludeOther",
		name = "Exclude 'Other' tab",
		description = "Never roll items from the Other tab (includes PvP pages)",
		position = 4
	)
	default boolean excludeOther()
	{
		return false;
	}
}

package com.orchardskydigital.clogslots;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.orchardskydigital.clogslots.difficulty.DifficultyIndex;
import com.orchardskydigital.clogslots.difficulty.Tier;
import com.orchardskydigital.clogslots.difficulty.TierOverrides;
import com.orchardskydigital.clogslots.log.AccountSummary;
import com.orchardskydigital.clogslots.log.ClogItem;
import com.orchardskydigital.clogslots.log.CollectionLogCatalog;
import com.orchardskydigital.clogslots.log.ObtainedItems;
import com.orchardskydigital.clogslots.log.PlayerNameTracker;
import com.orchardskydigital.clogslots.log.SyncButton;
import com.orchardskydigital.clogslots.log.SyncTracker;
import com.orchardskydigital.clogslots.roll.GoalRoller;
import com.orchardskydigital.clogslots.roll.GoalStore;
import com.orchardskydigital.clogslots.roll.RolledGoal;
import com.orchardskydigital.clogslots.ui.BundledArt;
import com.orchardskydigital.clogslots.ui.ClogSlotsPanel;
import com.orchardskydigital.clogslots.ui.GoalOverlay;
import com.orchardskydigital.clogslots.ui.PanelState;
import com.orchardskydigital.clogslots.ui.SlotMachineOverlay;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Collection Log Slots",
	description = "Roll your next collection log item on a slot machine, easiest tier first",
	tags = {"collection", "log", "clog", "goal", "random", "slots"}
)
public class ClogSlotsPlugin extends Plugin
{
	/** Fired by the game once per obtained item while the collection log draws items; args[1] is the item id. */
	private static final int COLLECTION_ITEM_SCRIPT = 4100;
	private static final Pattern NEW_ITEM_MESSAGE = Pattern.compile("New item added to your collection log: (.+)");
	private static final String CHAT_PREFIX = "<col=ff981f>Collection Log Slots:</col> ";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ClogSlotsConfig config;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private CollectionLogCatalog catalog;
	@Inject
	private SyncButton syncButton;
	@Inject
	private GoalStore store;
	@Inject
	private SlotMachineOverlay overlay;
	@Inject
	private GoalOverlay goalOverlay;
	@Inject
	private Gson gson;

	private final SyncTracker syncTracker = new SyncTracker();
	private final PlayerNameTracker playerName = new PlayerNameTracker();
	private DifficultyIndex difficulty;
	private GoalRoller roller;
	private ClogSlotsPanel panel;
	private NavigationButton navButton;
	private ObtainedItems obtained = new ObtainedItems();
	private int goalItemId = -1;
	private boolean obtainedDirty;

	@Override
	protected void startUp()
	{
		difficulty = loadDifficulty();
		roller = new GoalRoller(difficulty);
		panel = new ClogSlotsPanel(itemManager::getImage, this::requestRoll);
		navButton = NavigationButton.builder()
			.tooltip("Collection Log Slots")
			.icon(BundledArt.load("panel-icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
		overlayManager.add(goalOverlay);
		syncButton.setOnSync(this::startSync);
		clientThread.invokeLater(this::loadProfile);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		overlayManager.remove(goalOverlay);
		overlay.hide();
		clientThread.invokeLater(syncButton::remove);
	}

	@Provides
	ClogSlotsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClogSlotsConfig.class);
	}

	// ---- events ----

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		clientThread.invokeLater(this::loadProfile);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			clientThread.invokeLater(this::refreshPanel);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ClogSlotsConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(this::refreshPanel);
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == SyncButton.COLLECTION_LOG_SETUP_SCRIPT)
		{
			syncButton.add();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_ITEM_SCRIPT || event.getScriptEvent() == null)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args.length > 1 && args[1] instanceof Integer)
		{
			boolean isNew = obtained.add((Integer) args[1]);
			syncTracker.onItem(client.getTickCount(), isNew);
			if (isNew)
			{
				obtainedDirty = true;
				// batch the save + refresh: the search view fires this once per obtained item
				clientThread.invokeLater(this::flushObtained);
			}
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// the game's own collection log count, used for the "new items to sync" notice
		if (event.getVarpId() == VarPlayerID.COLLECTION_COUNT || event.getVarpId() == VarPlayerID.COLLECTION_COUNT_MAX)
		{
			refreshPanel();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Player local = client.getLocalPlayer();
		if (playerName.changed(local == null ? null : local.getName()))
		{
			refreshPanel();
		}
		syncTracker.onTick(client.getTickCount()).ifPresent(result ->
		{
			if (result.isEmpty())
			{
				chat("sync found no items. Make sure the Collection Log window is open, then click Clog Slots again.");
			}
			else
			{
				chat(String.format("synced %,d items (%,d new). Open the sidebar panel to roll!", result.getSeen(), result.getAdded()));
			}
			refreshPanel();
		});
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		Matcher m = NEW_ITEM_MESSAGE.matcher(Text.removeTags(event.getMessage()));
		if (!m.find())
		{
			return;
		}
		ensureCatalog();
		Integer itemId = catalog.idForName(m.group(1).trim());
		if (itemId == null || !obtained.add(itemId))
		{
			return;
		}
		obtainedDirty = true;
		flushObtained();
		if (itemId == goalItemId)
		{
			chat("goal complete! Roll your next one from the sidebar.");
		}
	}

	// ---- actions ----

	/** Called on the client thread when the in-log Clog Slots button is clicked. */
	private void startSync()
	{
		syncTracker.start(client.getTickCount());
		refreshPanel();
	}

	/** Called from the Swing thread when Roll is pressed. */
	private void requestRoll()
	{
		clientThread.invokeLater(() ->
		{
			ensureCatalog();
			Optional<RolledGoal> rolled = roller.roll(catalog.getItems(), obtained.asSet(), excludedTabs(), new Random());
			if (!rolled.isPresent())
			{
				chat("nothing left to roll. Your log is complete!");
				return;
			}
			RolledGoal goal = rolled.get();
			goalItemId = goal.getItem().getItemId();
			store.saveGoalItemId(goalItemId);
			SwingUtilities.invokeLater(() -> panel.showSpinning(true));
			overlay.spin(goal, config.spinSeconds() * 1000L, () ->
			{
				SwingUtilities.invokeLater(() -> panel.showSpinning(false));
				chat("your new goal is <col=ffffff>" + goal.getItem().getName() + "</col> ("
					+ goal.getTier().getDisplayName() + " tier, " + goal.getItem().getPage() + ").");
				refreshPanel();
			});
		});
	}

	private void loadProfile()
	{
		obtained = store.loadObtained();
		goalItemId = store.loadGoalItemId();
		refreshPanel();
	}

	private void flushObtained()
	{
		if (!obtainedDirty)
		{
			return;
		}
		obtainedDirty = false;
		store.saveObtained(obtained);
		refreshPanel();
	}

	private void ensureCatalog()
	{
		if (!catalog.isLoaded() && client.getGameState().getState() >= GameState.LOGIN_SCREEN.getState())
		{
			catalog.load();
		}
	}

	/** Builds the panel snapshot on the client thread and hands it to Swing. */
	private void refreshPanel()
	{
		ensureCatalog();
		List<ClogItem> items = catalog.getItems();
		Map<Tier, List<ClogItem>> missing = roller.missingByTier(items, obtained.asSet(), excludedTabs());
		Map<Tier, Integer> counts = new EnumMap<>(Tier.class);
		Tier rollingTier = null;
		for (Map.Entry<Tier, List<ClogItem>> e : missing.entrySet())
		{
			counts.put(e.getKey(), e.getValue().size());
			if (rollingTier == null && !e.getValue().isEmpty())
			{
				rollingTier = e.getKey();
			}
		}

		ClogItem goal = null;
		Tier goalTier = null;
		for (Map.Entry<Tier, List<ClogItem>> e : missing.entrySet())
		{
			for (ClogItem item : e.getValue())
			{
				if (item.getItemId() == goalItemId)
				{
					goal = item;
					goalTier = e.getKey();
				}
			}
		}
		boolean complete = false;
		if (goal == null && goalItemId >= 0)
		{
			// not missing any more (or excluded): show it as complete
			goal = items.stream().filter(i -> i.getItemId() == goalItemId).findFirst().orElse(null);
			complete = goal != null && obtained.contains(goalItemId);
		}

		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Player player = client.getLocalPlayer();
		PanelState state = PanelState.builder()
			.loggedIn(loggedIn)
			.playerName(loggedIn && player != null ? player.getName() : null)
			.syncing(syncTracker.isSyncing())
			.synced(obtained.size())
			.gameCount(loggedIn ? client.getVarpValue(VarPlayerID.COLLECTION_COUNT) : -1)
			.summary(items.isEmpty() ? null : AccountSummary.of(items, obtained.asSet()))
			.goal(goal)
			.goalTier(goalTier)
			.goalChance(goal == null ? null : difficulty.chanceOf(goal.getItemId()))
			.goalComplete(complete)
			.remainingByTier(counts)
			.rollingTier(rollingTier)
			.build();
		goalOverlay.setGoal(goal, goalTier, complete);
		SwingUtilities.invokeLater(() -> panel.update(state));
	}

	private void chat(String message)
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", CHAT_PREFIX + message, null);
		}
	}

	private Set<String> excludedTabs()
	{
		return config.excludeOther() ? Collections.singleton("Other") : Collections.emptySet();
	}

	private DifficultyIndex loadDifficulty()
	{
		TierOverrides overrides = loadOverrides();
		try (Reader reader = new InputStreamReader(
			ClogSlotsPlugin.class.getResourceAsStream("item-chance.json"), StandardCharsets.UTF_8))
		{
			return DifficultyIndex.fromJson(gson, reader, overrides);
		}
		catch (Exception e)
		{
			log.warn("Could not load item-chance.json; every item will use the default difficulty", e);
			return new DifficultyIndex(Collections.emptyMap(), overrides);
		}
	}

	private TierOverrides loadOverrides()
	{
		InputStream in = ClogSlotsPlugin.class.getResourceAsStream("tier-overrides.json");
		if (in == null)
		{
			return TierOverrides.none();
		}
		try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			return TierOverrides.fromJson(gson, reader);
		}
		catch (Exception e)
		{
			log.warn("Could not load tier-overrides.json; using automatic tiers only", e);
			return TierOverrides.none();
		}
	}
}

package com.orchardskydigital.clogslots.difficulty;

/** Human-readable drop chance, e.g. "1 in 512". */
public final class ChanceText
{
	private ChanceText()
	{
	}

	public static String format(double chance)
	{
		if (chance >= 1)
		{
			return "Guaranteed";
		}
		return String.format("1 in %,d", Math.round(1 / chance));
	}
}

package com.orchardskydigital.clogslots.difficulty;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.Reader;
import java.util.Collection;
import java.util.Map;

/**
 * Scores collection log items by rarity, using bundled drop chances from the OSRS Wiki.
 * Items without a drop chance (shop, recipe, ...) take the median score of their page.
 * Hand-picked {@link TierOverrides} win over the score.
 */
public class DifficultyIndex
{
	/** Score used when neither the item nor its page has any data (lands in HARD). */
	public static final double DEFAULT_SCORE = 2.5;

	private final Map<Integer, Double> chances;
	private final TierOverrides overrides;

	public DifficultyIndex(Map<Integer, Double> chances)
	{
		this(chances, TierOverrides.none());
	}

	public DifficultyIndex(Map<Integer, Double> chances, TierOverrides overrides)
	{
		this.chances = chances;
		this.overrides = overrides;
	}

	public static DifficultyIndex fromJson(Gson gson, Reader reader)
	{
		return fromJson(gson, reader, TierOverrides.none());
	}

	public static DifficultyIndex fromJson(Gson gson, Reader reader, TierOverrides overrides)
	{
		Map<Integer, Double> chances = gson.fromJson(reader, new TypeToken<Map<Integer, Double>>()
		{
		}.getType());
		return new DifficultyIndex(chances, overrides);
	}

	public double scoreOf(int itemId, Collection<Integer> pageItemIds)
	{
		Double chance = chances.get(itemId);
		if (chance != null)
		{
			return score(chance);
		}
		double[] pageScores = pageItemIds.stream()
			.map(chances::get)
			.filter(c -> c != null)
			.mapToDouble(DifficultyIndex::score)
			.sorted()
			.toArray();
		if (pageScores.length == 0)
		{
			return DEFAULT_SCORE;
		}
		int mid = pageScores.length / 2;
		return pageScores.length % 2 == 1 ? pageScores[mid] : (pageScores[mid - 1] + pageScores[mid]) / 2;
	}

	/** Best drop chance for the item, or null when it only comes from shops/recipes. */
	public Double chanceOf(int itemId)
	{
		return chances.get(itemId);
	}

	public Tier tierOf(int itemId, String page, Collection<Integer> pageItemIds)
	{
		Tier picked = overrides.tierFor(itemId, page);
		return picked != null ? picked : Tier.forScore(scoreOf(itemId, pageItemIds));
	}

	private static double score(double chance)
	{
		return -Math.log10(chance);
	}
}

package com.orchardskydigital.clogslots.difficulty;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** Difficulty bands over the item score (-log10 of the best drop chance). */
@Getter
@RequiredArgsConstructor
public enum Tier
{
	EASY("Easy", 1.0),      // better than 1/10
	MEDIUM("Medium", 2.0),  // better than 1/100
	HARD("Hard", 2.7),      // better than ~1/500
	ELITE("Elite", 3.5),    // better than ~1/3,000
	MASTER("Master", Double.POSITIVE_INFINITY);

	private final String displayName;
	private final double upperBound;

	public static Tier forScore(double score)
	{
		for (Tier tier : values())
		{
			if (score < tier.upperBound)
			{
				return tier;
			}
		}
		return MASTER;
	}
}

package com.orchardskydigital.clogslots.difficulty;

import com.google.gson.Gson;
import java.io.Reader;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Hand-picked tiers from the tier sorter, bundled as tier-overrides.json:
 * {"pages": {"Tombs of Amascut": "ELITE"}, "items": {"27378": "ELITE"}}.
 * An item entry beats its page's entry, which beats the automatic score.
 */
public class TierOverrides
{
	private final Map<String, Tier> pages;
	private final Map<Integer, Tier> items;

	private TierOverrides(Map<String, Tier> pages, Map<Integer, Tier> items)
	{
		this.pages = pages;
		this.items = items;
	}

	public static TierOverrides none()
	{
		return new TierOverrides(Collections.emptyMap(), Collections.emptyMap());
	}

	public static TierOverrides fromJson(Gson gson, Reader reader)
	{
		Raw raw = gson.fromJson(reader, Raw.class);
		Map<String, Tier> pages = new HashMap<>();
		Map<Integer, Tier> items = new HashMap<>();
		if (raw != null && raw.pages != null)
		{
			raw.pages.forEach((page, tier) -> pages.put(page, Tier.valueOf(tier)));
		}
		if (raw != null && raw.items != null)
		{
			raw.items.forEach((id, tier) -> items.put(Integer.parseInt(id), Tier.valueOf(tier)));
		}
		return new TierOverrides(pages, items);
	}

	/** @return the hand-picked tier for this item on this page, or null to use the automatic score */
	public Tier tierFor(int itemId, String page)
	{
		Tier item = items.get(itemId);
		return item != null ? item : pages.get(page);
	}

	public int size()
	{
		return pages.size() + items.size();
	}

	private static class Raw
	{
		Map<String, String> pages;
		Map<String, String> items;
	}
}

package com.orchardskydigital.clogslots.log;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/** Obtained/total counts for the whole log and per tab. Items on several pages count once. */
@Value
public class AccountSummary
{
	int obtained;
	int total;
	List<TabProgress> tabs;

	@Value
	public static class TabProgress
	{
		String name;
		int obtained;
		int total;
	}

	public static AccountSummary of(Collection<ClogItem> catalog, Set<Integer> obtainedIds)
	{
		Set<Integer> all = new HashSet<>();
		Map<String, Set<Integer>> byTab = new LinkedHashMap<>();
		for (ClogItem item : catalog)
		{
			all.add(item.getItemId());
			byTab.computeIfAbsent(item.getTab(), t -> new HashSet<>()).add(item.getItemId());
		}
		List<TabProgress> tabs = new ArrayList<>();
		byTab.forEach((tab, ids) -> tabs.add(new TabProgress(tab, countObtained(ids, obtainedIds), ids.size())));
		return new AccountSummary(countObtained(all, obtainedIds), all.size(), tabs);
	}

	private static int countObtained(Set<Integer> ids, Set<Integer> obtainedIds)
	{
		return (int) ids.stream().filter(obtainedIds::contains).count();
	}
}

package com.orchardskydigital.clogslots.log;

import lombok.Value;

/** One slot in the collection log, located by the page and tab it appears on. */
@Value
public class ClogItem
{
	int itemId;
	String name;
	String page;
	String tab;
}

package com.orchardskydigital.clogslots.log;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.client.game.ItemManager;

/**
 * Every collection log slot, read from the game cache (no hardcoded item list).
 * Must be built on the client thread.
 */
@Slf4j
@Singleton
public class CollectionLogCatalog
{
	private static final int TABS_ENUM = 2102;
	private static final int TAB_PAGES_PARAM = 683;
	private static final int PAGE_NAME_PARAM = 689;
	private static final int PAGE_ITEMS_PARAM = 690;
	private static final int ITEM_REPLACEMENTS_ENUM = 3721;
	private static final String[] TAB_NAMES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};

	private final Client client;
	private final ItemManager itemManager;

	@Getter
	private List<ClogItem> items = Collections.emptyList();
	private Map<String, Integer> idsByName = Collections.emptyMap();

	@Inject
	CollectionLogCatalog(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	public boolean isLoaded()
	{
		return !items.isEmpty();
	}

	public void load()
	{
		EnumComposition replacements = client.getEnum(ITEM_REPLACEMENTS_ENUM);
		Map<Integer, Integer> replace = new HashMap<>();
		int[] keys = replacements.getKeys();
		int[] values = replacements.getIntVals();
		for (int i = 0; i < keys.length; i++)
		{
			replace.put(keys[i], values[i]);
		}

		List<ClogItem> loaded = new ArrayList<>();
		Map<String, Integer> byName = new HashMap<>();
		int[] tabStructs = client.getEnum(TABS_ENUM).getIntVals();
		for (int t = 0; t < tabStructs.length; t++)
		{
			String tab = t < TAB_NAMES.length ? TAB_NAMES[t] : "Tab " + t;
			StructComposition tabStruct = client.getStructComposition(tabStructs[t]);
			for (int pageStructId : client.getEnum(tabStruct.getIntValue(TAB_PAGES_PARAM)).getIntVals())
			{
				StructComposition pageStruct = client.getStructComposition(pageStructId);
				String page = pageName(pageStruct, pageStructId);
				for (int rawId : client.getEnum(pageStruct.getIntValue(PAGE_ITEMS_PARAM)).getIntVals())
				{
					int itemId = replace.getOrDefault(rawId, rawId);
					String name = itemManager.getItemComposition(itemId).getName();
					loaded.add(new ClogItem(itemId, name, page, tab));
					byName.putIfAbsent(name.toLowerCase(), itemId);
				}
			}
		}
		items = Collections.unmodifiableList(loaded);
		idsByName = byName;
		log.debug("Collection log catalog loaded: {} slots", items.size());
	}

	/** Item id for a name as printed in the "New item added to your collection log" message, or null. */
	public Integer idForName(String name)
	{
		return idsByName.get(name.toLowerCase());
	}

	private static String pageName(StructComposition pageStruct, int structId)
	{
		String name = pageStruct.getStringValue(PAGE_NAME_PARAM);
		return name == null || name.isEmpty() ? "Page " + structId : name;
	}
}

package com.orchardskydigital.clogslots.log;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.stream.Collectors;

/** The set of collection log item ids the player has obtained. Only ever grows. */
public class ObtainedItems
{
	private final Set<Integer> itemIds = new HashSet<>();

	/** @return true if the item was not already recorded */
	public boolean add(int itemId)
	{
		return itemIds.add(itemId);
	}

	public boolean contains(int itemId)
	{
		return itemIds.contains(itemId);
	}

	public int size()
	{
		return itemIds.size();
	}

	public Set<Integer> asSet()
	{
		return Collections.unmodifiableSet(itemIds);
	}

	public String encode()
	{
		return itemIds.stream().sorted().map(String::valueOf).collect(Collectors.joining(","));
	}

	public static ObtainedItems decode(String encoded)
	{
		var items = new ObtainedItems();
		if (encoded == null)
		{
			return items;
		}
		for (String part : encoded.split(","))
		{
			try
			{
				items.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException ignored)
			{
				// skip blanks and corrupt entries
			}
		}
		return items;
	}
}

package com.orchardskydigital.clogslots.log;

import java.util.Objects;

/**
 * Notices when the logged-in player's name becomes known or changes. The name is often still
 * missing on the LOGGED_IN event, so the panel re-checks on each tick until it appears.
 */
public class PlayerNameTracker
{
	private String last;

	/** @return true if {@code current} differs from the name seen last time */
	public boolean changed(String current)
	{
		if (Objects.equals(last, current))
		{
			return false;
		}
		last = current;
		return true;
	}
}

