import net.runelite.api.widgets.WidgetType;

/**
 * Adds a "Sync" button to the collection log. Clicking it opens the log's search view,
 * which makes the game run script 4100 for every obtained item in one pass.
 * Same approach as WikiSync; Client#menuAction is permitted for loading collection log data.
 */
@Singleton
public class SyncButton
{
	public static final int COLLECTION_LOG_SETUP_SCRIPT = 7797;
	private static final int SEARCH_LOAD_SCRIPT = 2240;
	private static final int WIDTH = 64;
	// offset from the right edge, clear of the close button and of WikiSync's button
	private static final int X_FROM_RIGHT = 110;
	private static final int BACKGROUND = 0x3e3529;
	private static final int TEXT_IDLE = 0xff981f;
	private static final int TEXT_HOVER = 0xffffff;

	private final Client client;
	private final List<Widget> widgets = new ArrayList<>();
	/** Runs on the client thread just before the search view is opened. */
	@Setter
	private Runnable onSync = () ->
	{
	};

	@Inject
	SyncButton(Client client)
	{
		this.client = client;
	}

	/** Call on the client thread after the collection log interface is built. */
	public void add()
	{
		remove();
		Widget parent = client.getWidget(InterfaceID.Collection.UNIVERSE);
		Widget search = client.getWidget(InterfaceID.Collection.SEARCH_TOGGLE);
		if (parent == null || search == null)
		{
			return;
		}
		int y = search.getOriginalY();
		int h = search.getOriginalHeight();

		Widget background = parent.createChild(-1, WidgetType.RECTANGLE);
		background.setFilled(true);
		background.setTextColor(BACKGROUND);
		place(background, y, h);

		Widget text = parent.createChild(-1, WidgetType.TEXT);
		text.setText("Clog Slots");
		text.setTextColor(TEXT_IDLE);
		text.setFontId(FontID.PLAIN_11);
		text.setTextShadowed(true);
		text.setXTextAlignment(WidgetTextAlignment.CENTER);
		text.setYTextAlignment(WidgetTextAlignment.CENTER);
		text.setHasListener(true);
		text.setAction(0, "Sync");
		text.setOnOpListener((JavaScriptCallback) e -> sync());
		text.setOnMouseOverListener((JavaScriptCallback) e -> text.setTextColor(TEXT_HOVER));
		text.setOnMouseLeaveListener((JavaScriptCallback) e -> text.setTextColor(TEXT_IDLE));
		place(text, y, h);

		widgets.add(background);
		widgets.add(text);
	}

	public void remove()
	{
		widgets.forEach(w -> w.setHidden(true));
		widgets.clear();
	}

	private void sync()
	{
		onSync.run();
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(SEARCH_LOAD_SCRIPT);
	}

	private static void place(Widget widget, int y, int h)
	{
		widget.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		widget.setPos(X_FROM_RIGHT, y);
		widget.setSize(WIDTH, h);
		widget.revalidate();
	}
}

package com.orchardskydigital.clogslots.log;

import java.util.Optional;
import lombok.Getter;
import lombok.Value;

/**
 * Tracks one sync: the game fires the item script for every obtained item over a tick or two
 * after the search view opens. The sync is done once no item has arrived for a couple of ticks.
 */
public class SyncTracker
{
	private static final int QUIET_TICKS = 2;
	private static final int TIMEOUT_TICKS = 5;

	@Getter
	private boolean syncing;
	private int startTick;
	private int lastItemTick;
	private int seen;
	private int added;

	@Value
	public static class Result
	{
		int seen;
		int added;

		public boolean isEmpty()
		{
			return seen == 0;
		}
	}

	public void start(int tick)
	{
		syncing = true;
		startTick = tick;
		lastItemTick = -1;
		seen = 0;
		added = 0;
	}

	public void onItem(int tick, boolean wasNew)
	{
		if (!syncing)
		{
			return;
		}
		lastItemTick = tick;
		seen++;
		if (wasNew)
		{
			added++;
		}
	}

	/** @return the result when the sync has just finished */
	public Optional<Result> onTick(int tick)
	{
		if (!syncing)
		{
			return Optional.empty();
		}
		boolean quiet = seen > 0 && tick - lastItemTick >= QUIET_TICKS;
		boolean timedOut = seen == 0 && tick - startTick >= TIMEOUT_TICKS;
		if (!quiet && !timedOut)
		{
			return Optional.empty();
		}
		syncing = false;
		return Optional.of(new Result(seen, added));
	}
}

package com.orchardskydigital.clogslots.roll;

import com.orchardskydigital.clogslots.difficulty.DifficultyIndex;
import com.orchardskydigital.clogslots.difficulty.Tier;
import com.orchardskydigital.clogslots.log.ClogItem;
import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;

/** Picks a random missing item from the easiest tier that still has missing items. */
public class GoalRoller
{
	private final DifficultyIndex difficulty;

	public GoalRoller(DifficultyIndex difficulty)
	{
		this.difficulty = difficulty;
	}

	public Optional<RolledGoal> roll(Collection<ClogItem> catalog, Set<Integer> obtained, Set<String> excludedTabs, Random random)
	{
		Map<Tier, List<ClogItem>> byTier = missingByTier(catalog, obtained, excludedTabs);
		for (Map.Entry<Tier, List<ClogItem>> entry : byTier.entrySet())
		{
			List<ClogItem> candidates = entry.getValue();
			if (!candidates.isEmpty())
			{
				ClogItem pick = candidates.get(random.nextInt(candidates.size()));
				return Optional.of(new RolledGoal(pick, entry.getKey(), candidates));
			}
		}
		return Optional.empty();
	}

	/** Missing, non-excluded items grouped by tier, easiest first. Items on several pages count once. */
	public Map<Tier, List<ClogItem>> missingByTier(Collection<ClogItem> catalog, Set<Integer> obtained, Set<String> excludedTabs)
	{
		Map<String, List<Integer>> pageItems = catalog.stream()
			.collect(Collectors.groupingBy(ClogItem::getPage, Collectors.mapping(ClogItem::getItemId, Collectors.toList())));

		Map<Integer, ClogItem> unique = new LinkedHashMap<>();
		for (ClogItem item : catalog)
		{
			if (!obtained.contains(item.getItemId()) && !excludedTabs.contains(item.getTab()))
			{
				unique.putIfAbsent(item.getItemId(), item);
			}
		}

		Map<Tier, List<ClogItem>> byTier = new EnumMap<>(Tier.class);
		for (Tier tier : Tier.values())
		{
			byTier.put(tier, new ArrayList<>());
		}
		for (ClogItem item : unique.values())
		{
			byTier.get(difficulty.tierOf(item.getItemId(), item.getPage(), pageItems.get(item.getPage()))).add(item);
		}
		return byTier;
	}
}

package com.orchardskydigital.clogslots.roll;

import com.orchardskydigital.clogslots.ClogSlotsConfig;
import com.orchardskydigital.clogslots.log.ObtainedItems;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/** Per-account persistence for obtained items and the active goal. */
@Singleton
public class GoalStore
{
	private static final String OBTAINED_KEY = "obtained";
	private static final String GOAL_KEY = "goalItemId";

	private final ConfigManager configManager;

	@Inject
	GoalStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public ObtainedItems loadObtained()
	{
		return ObtainedItems.decode(configManager.getRSProfileConfiguration(ClogSlotsConfig.GROUP, OBTAINED_KEY));
	}

	public void saveObtained(ObtainedItems items)
	{
		configManager.setRSProfileConfiguration(ClogSlotsConfig.GROUP, OBTAINED_KEY, items.encode());
	}

	/** @return the active goal's item id, or -1 */
	public int loadGoalItemId()
	{
		String value = configManager.getRSProfileConfiguration(ClogSlotsConfig.GROUP, GOAL_KEY);
		try
		{
			return value == null ? -1 : Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	public void saveGoalItemId(int itemId)
	{
		if (itemId < 0)
		{
			configManager.unsetRSProfileConfiguration(ClogSlotsConfig.GROUP, GOAL_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(ClogSlotsConfig.GROUP, GOAL_KEY, itemId);
		}
	}
}

