/**
 * Sidebar. Before the first sync it is an onboarding card; afterwards it leads with the current goal
 * and Roll button, then account progress, then the tier breakdown.
 */
public class ClogSlotsPanel extends PluginPanel
{
	private static final Color TAB_BAR = new Color(0xa8823e);
	/** PluginPanel.PANEL_WIDTH minus this panel's side padding. */
	private static final int CONTENT_WIDTH = PluginPanel.PANEL_WIDTH - 20;
	private static final int CARD_WIDTH = CONTENT_WIDTH - 2 * Theme.PAD;
	private static final int STEP_WIDTH = CARD_WIDTH - 32;
	private static final int GOAL_NAME_WIDTH = CARD_WIDTH - 56;

	private final IntFunction<AsyncBufferedImage> itemIcons;
	private final JPanel content = new JPanel();
	private final ArtButton rollButton = new ArtButton(Art.BUTTON, Art.BUTTON_HOVER, 40);
	private boolean spinning;

	public ClogSlotsPanel(IntFunction<AsyncBufferedImage> itemIcons, Runnable onRoll)
	{
		this.itemIcons = itemIcons;
		setLayout(new BorderLayout());
		setBackground(Theme.BACKGROUND);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);
		add(content, BorderLayout.NORTH);

		rollButton.setFont(FontManager.getRunescapeBoldFont());
		rollButton.addActionListener(e -> onRoll.run());

		update(PanelState.builder().gameCount(-1).build());
	}

	/** Call on the Swing thread. */
	public void update(PanelState state)
	{
		content.removeAll();
		stack(header(state));
		if (!state.hasSynced() || state.isSyncing())
		{
			stack(onboarding(state));
		}
		else
		{
			if (state.behindBy() > 0)
			{
				stack(resyncNotice(state.behindBy()));
			}
			stack(goalCard(state));
			stack(rollArea(state));
			if (state.getSummary() != null)
			{
				stack(progressCard(state.getSummary()));
			}
			stack(tierCard(state));
			stack(footnote("New items are picked up automatically. To re-sync, open the Collection Log and click Clog Slots."));
		}
		content.revalidate();
		content.repaint();
	}

	public void showSpinning(boolean spinning)
	{
		this.spinning = spinning;
		rollButton.setEnabled(!spinning);
		if (spinning)
		{
			rollButton.setText("Spinning…");
		}
	}

	// ---- sections ----

	private JComponent header(PanelState state)
	{
		JPanel p = column();
		p.add(text("Collection Log Slots", FontManager.getRunescapeBoldFont(), Theme.RS_ORANGE));
		p.add(Box.createVerticalStrut(4));
		JPanel sub = row();
		sub.add(text(state.accountLabel(), Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
		sub.add(statusChip(state), BorderLayout.EAST);
		p.add(sub);
		return p;
	}

	private static JComponent statusChip(PanelState state)
	{
		if (state.isSyncing())
		{
			return new Chip("Syncing", Theme.WARNING, Theme.label(), null);
		}
		if (!state.hasSynced())
		{
			return new Chip("Not synced", Theme.TEXT_MUTED, Theme.label(), null);
		}
		if (state.behindBy() > 0)
		{
			return new Chip("Out of date", Theme.WARNING, Theme.label(), null);
		}
		return new Chip("● Synced", Theme.SUCCESS, Theme.label(), null);
	}

	private JComponent onboarding(PanelState state)
	{
		JPanel card = card();
		if (state.isSyncing())
		{
			card.add(text("Reading your collection log…", Theme.font(Font.BOLD, 13f), Theme.TEXT));
			card.add(Box.createVerticalStrut(4));
			card.add(new WrapText("This only takes a second.", Theme.body(), Theme.TEXT_MUTED, CARD_WIDTH));
			return card;
		}
		if (!state.isLoggedIn())
		{
			card.add(text("Log in to get started", Theme.font(Font.BOLD, 13f), Theme.TEXT));
			card.add(Box.createVerticalStrut(4));
			card.add(new WrapText("Once you're in game, this panel walks you through a one-time sync of your collection log.",
				Theme.body(), Theme.TEXT_MUTED, CARD_WIDTH));
			return card;
		}
		card.add(new WrapText("Sync your collection log", Theme.font(Font.BOLD, 13f), Theme.TEXT, CARD_WIDTH));
		card.add(Box.createVerticalStrut(4));
		card.add(new WrapText("A one-time step so the plugin knows what you already have.", Theme.body(), Theme.TEXT_MUTED, CARD_WIDTH));
		card.add(Box.createVerticalStrut(10));
		card.add(step(1, "Open the Collection Log", "Character Summary tab → Collection Log"));
		card.add(Box.createVerticalStrut(8));
		card.add(step(2, "Click \"Clog Slots\"", "The orange button at the top right of the log window"));
		card.add(Box.createVerticalStrut(8));
		card.add(step(3, "Come back here", "Your progress shows up and you can roll"));
		return card;
	}

	private JComponent resyncNotice(int behindBy)
	{
		RoundedPanel card = new RoundedPanel(null, new Color(0x3a2f14), Theme.RADIUS);
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBorder(new EmptyBorder(10, Theme.PAD, 10, Theme.PAD));
		card.add(text(String.format("%,d new item%s to sync", behindBy, behindBy == 1 ? "" : "s"), Theme.font(Font.BOLD, 12f), Theme.WARNING));
		card.add(Box.createVerticalStrut(2));
		card.add(new WrapText("Open the Collection Log and click Clog Slots.", Theme.small(), Theme.TEXT_MUTED, CARD_WIDTH));
		return card;
	}

	private JComponent goalCard(PanelState state)
	{
		JPanel card = card();
		card.add(sectionLabel("CURRENT GOAL"));
		card.add(Box.createVerticalStrut(8));
		if (state.getGoal() == null)
		{
			card.add(text("No goal yet", Theme.font(Font.BOLD, 14f), Theme.TEXT));
			card.add(Box.createVerticalStrut(2));
			card.add(new WrapText("Hit Roll to spin the slot machine for your next item.", Theme.body(), Theme.TEXT_MUTED, CARD_WIDTH));
			return card;
		}

		JPanel top = new JPanel(new BorderLayout(10, 0));
		top.setOpaque(false);
		top.add(itemTile(state.getGoal().getItemId()), BorderLayout.WEST);
		JPanel names = column();
		names.add(Box.createVerticalStrut(3));
		names.add(new WrapText(state.getGoal().getName(), Theme.font(Font.BOLD, 14f), Theme.TEXT, GOAL_NAME_WIDTH));
		names.add(Box.createVerticalStrut(2));
		names.add(new WrapText(state.getGoal().getPage(), Theme.small(), Theme.TEXT_MUTED, GOAL_NAME_WIDTH));
		top.add(names, BorderLayout.CENTER);
		card.add(fit(top));
		card.add(Box.createVerticalStrut(10));

		JPanel chips = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		chips.setOpaque(false);
		if (state.isGoalComplete())
		{
			chips.add(new Chip("✓ Complete", Theme.SUCCESS, Theme.label(), null));
		}
		else
		{
			Tier tier = state.getGoalTier();
			chips.add(new Chip(tier.getDisplayName(), Theme.tierColor(tier), Theme.label(), badge(tier, 14)));
			chips.add(Box.createHorizontalStrut(6));
			String chance = state.getGoalChance() == null ? "No drop rate" : ChanceText.format(state.getGoalChance());
			chips.add(new Chip(chance, Theme.TEXT_MUTED, Theme.label(), null));
		}
		card.add(fit(chips));
		return card;
	}

	private JComponent rollArea(PanelState state)
	{
		JPanel p = column();
		if (!spinning)
		{
			boolean done = state.getRollingTier() == null;
			rollButton.setEnabled(!done);
			rollButton.setText(done ? "Log complete!"
				: state.getGoal() == null || state.isGoalComplete() ? "Roll" : "Re-roll");
		}
		rollButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(rollButton);
		if (state.getRollingTier() != null)
		{
			int left = state.getRemainingByTier().getOrDefault(state.getRollingTier(), 0);
			p.add(Box.createVerticalStrut(6));
			JLabel caption = text(String.format("Next roll: %s tier · %,d items", state.getRollingTier().getDisplayName(), left),
				Theme.small(), Theme.TEXT_FAINT);
			JPanel centered = new JPanel(new GridBagLayout());
			centered.setOpaque(false);
			centered.add(caption);
			p.add(fit(centered));
		}
		return p;
	}

	private JComponent progressCard(AccountSummary summary)
	{
		JPanel card = card();
		card.add(sectionLabel("COLLECTION LOG"));
		card.add(Box.createVerticalStrut(6));

		JPanel headline = row();
		JPanel numbers = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		numbers.setOpaque(false);
		numbers.add(text(String.format("%,d", summary.getObtained()), Theme.font(Font.BOLD, 22f), Theme.TEXT));
		numbers.add(text(String.format(" / %,d", summary.getTotal()), Theme.font(Font.PLAIN, 13f), Theme.TEXT_MUTED));
		headline.add(numbers, BorderLayout.WEST);
		double pct = summary.getTotal() == 0 ? 0 : 100.0 * summary.getObtained() / summary.getTotal();
		headline.add(text(String.format("%.1f%%", pct), Theme.font(Font.BOLD, 12f), Theme.ACCENT), BorderLayout.EAST);
		card.add(headline);
		card.add(Box.createVerticalStrut(6));
		card.add(new SlimBar(summary.getObtained(), summary.getTotal(), 8, Theme.TRACK, Theme.ACCENT));

		for (AccountSummary.TabProgress tab : summary.getTabs())
		{
			card.add(Box.createVerticalStrut(10));
			JPanel r = row();
			r.add(text(tab.getName(), Theme.body(), Theme.TEXT), BorderLayout.WEST);
			r.add(text(String.format("%,d / %,d", tab.getObtained(), tab.getTotal()), Theme.small(), Theme.TEXT_MUTED), BorderLayout.EAST);
			card.add(r);
			card.add(Box.createVerticalStrut(4));
			boolean complete = tab.getObtained() >= tab.getTotal();
			card.add(new SlimBar(tab.getObtained(), tab.getTotal(), 4, Theme.TRACK, complete ? Theme.SUCCESS : TAB_BAR));
		}
		return card;
	}

	private JComponent tierCard(PanelState state)
	{
		JPanel card = card();
		card.add(sectionLabel("MISSING BY TIER"));
		card.add(Box.createVerticalStrut(6));
		for (Tier tier : Tier.values())
		{
			int left = state.getRemainingByTier() == null ? 0 : state.getRemainingByTier().getOrDefault(tier, 0);
			boolean next = tier == state.getRollingTier();
			boolean done = left == 0;

			JPanel r = row();
			r.setBorder(new EmptyBorder(4, 0, 4, 0));
			JPanel name = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			name.setOpaque(false);
			JLabel label = text(tier.getDisplayName(), Theme.body(), done ? Theme.TEXT_FAINT : Theme.TEXT);
			label.setIcon(badge(tier, 18));
			label.setIconTextGap(8);
			name.add(label);
			if (next)
			{
				name.add(Box.createHorizontalStrut(6));
				name.add(new Chip("NEXT", Theme.ACCENT, Theme.font(Font.BOLD, 9f), null));
			}
			r.add(name, BorderLayout.WEST);
			r.add(text(done ? "✓" : String.format("%,d", left), Theme.body(), done ? Theme.SUCCESS : Theme.TEXT_MUTED), BorderLayout.EAST);
			card.add(r);
		}
		card.add(Box.createVerticalStrut(6));
		card.add(new WrapText("Rolls always come from the easiest tier you still have items in.", Theme.small(), Theme.TEXT_FAINT, CARD_WIDTH));
		return card;
	}

	private static JComponent footnote(String s)
	{
		JPanel p = column();
		p.setBorder(new EmptyBorder(0, 4, 0, 4));
		p.add(new WrapText(s, Theme.small(), Theme.TEXT_FAINT, CONTENT_WIDTH - 8));
		return p;
	}

	// ---- building blocks ----

	private void stack(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(c);
		content.add(Box.createVerticalStrut(Theme.GAP));
	}

	private static JPanel card()
	{
		ArtCard card = new ArtCard(null, Art.CARD);
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBorder(new EmptyBorder(Theme.PAD, Theme.PAD, Theme.PAD, Theme.PAD));
		return card;
	}

	private static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		return p;
	}

	/** Full-width row with WEST/EAST slots that doesn't stretch vertically. */
	private static JPanel row()
	{
		JPanel p = new JPanel(new BorderLayout(8, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** Stops BoxLayout stretching a component taller than it wants to be. */
	private static JComponent fit(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		return c;
	}

	private static JLabel text(String s, Font font, Color color)
	{
		JLabel l = new JLabel(s);
		l.setFont(font);
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel sectionLabel(String s)
	{
		return text(s, FontManager.getRunescapeSmallFont(), Theme.RS_ORANGE);
	}

	private static JComponent step(int number, String title, String detail)
	{
		JPanel r = new JPanel(new BorderLayout(10, 0));
		r.setOpaque(false);
		r.setAlignmentX(Component.LEFT_ALIGNMENT);

		RoundedPanel dot = new RoundedPanel(new GridBagLayout(), Theme.ACCENT, 11);
		dot.setPreferredSize(new Dimension(22, 22));
		dot.setMaximumSize(new Dimension(22, 22));
		dot.add(text(String.valueOf(number), Theme.font(Font.BOLD, 11f), Theme.ON_ACCENT));
		JPanel dotHolder = column();
		dotHolder.add(dot);
		r.add(dotHolder, BorderLayout.WEST);

		JPanel words = column();
		words.add(new WrapText(title, Theme.font(Font.BOLD, 12f), Theme.TEXT, STEP_WIDTH));
		words.add(Box.createVerticalStrut(1));
		words.add(new WrapText(detail, Theme.small(), Theme.TEXT_MUTED, STEP_WIDTH));
		r.add(words, BorderLayout.CENTER);
		return fit(r);
	}

	private JComponent itemTile(int itemId)
	{
		RoundedPanel tile = new RoundedPanel(new GridBagLayout(), Theme.CARD_HOVER, 8);
		tile.setPreferredSize(new Dimension(46, 46));
		JLabel icon = new JLabel();
		itemIcons.apply(itemId).addTo(icon);
		tile.add(icon);
		JPanel holder = column();
		holder.add(tile);
		return holder;
	}

	private static ImageIcon badge(Tier tier, int size)
	{
		return new ImageIcon(TierIcons.get(tier).getScaledInstance(size, size, Image.SCALE_SMOOTH));
	}
}

package com.orchardskydigital.clogslots.ui;

import com.orchardskydigital.clogslots.ClogSlotsConfig;
import com.orchardskydigital.clogslots.difficulty.Tier;
import com.orchardskydigital.clogslots.log.ClogItem;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** Optional on-screen plaque showing the current goal. Toggled with "Show goal on screen". */
@Singleton
public class GoalOverlay extends Overlay
{
	private static final int WIDTH = 300;
	private static final int HEIGHT = WIDTH * Art.GOAL_PLAQUE.getHeight() / Art.GOAL_PLAQUE.getWidth();
	// Areas inside goal-plaque.png as fractions of its size (measured by tools/process_ui_art.py).
	private static final Rectangle ICON_SLOT = frac(0.057, 0.312, 0.127, 0.376);
	private static final Rectangle TEXT_AREA = frac(0.217, 0.290, 0.740, 0.460);
	// The scroll's flat parchment, between its curled ends.
	private static final Rectangle RIBBON = frac(0.413, 0.108, 0.167, 0.129);

	private static final Color NAME = new Color(0xffffff);
	private static final Color DETAIL = new Color(0xff981f);
	private static final Color DONE = new Color(0x4ade80);
	private static final Color RIBBON_TEXT = new Color(0x2b1a08);

	private final ItemManager itemManager;
	private final ClogSlotsConfig config;

	private volatile ClogItem goal;
	private volatile Tier tier;
	private volatile boolean complete;

	@Inject
	GoalOverlay(ItemManager itemManager, ClogSlotsConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.LOW);
		setMovable(true);
	}

	public void setGoal(ClogItem goal, Tier tier, boolean complete)
	{
		this.goal = goal;
		this.tier = tier;
		this.complete = complete;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		ClogItem item = goal;
		if (!config.showGoalOverlay() || item == null)
		{
			return null;
		}
		paint(g, itemManager.getImage(item.getItemId()), item, tier, complete);
		return new Dimension(WIDTH, HEIGHT);
	}

	/** Draws the plaque at the origin; separate from {@link #render} so it can be previewed without a client. */
	public static void paint(Graphics2D g, BufferedImage icon, ClogItem item, Tier tier, boolean complete)
	{
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(Art.GOAL_PLAQUE, 0, 0, WIDTH, HEIGHT, null);

		g.setFont(FontManager.getRunescapeBoldFont());
		centered(g, complete ? "DONE!" : "GOAL", RIBBON, RIBBON_TEXT);

		g.drawImage(icon, ICON_SLOT.x + (ICON_SLOT.width - icon.getWidth()) / 2,
			ICON_SLOT.y + (ICON_SLOT.height - icon.getHeight()) / 2, null);

		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics bold = g.getFontMetrics();
		int lineY = TEXT_AREA.y + bold.getAscent() + 1;
		shadow(g, fit(g, item.getName(), TEXT_AREA.width), TEXT_AREA.x, lineY, NAME);

		g.setFont(FontManager.getRunescapeSmallFont());
		int detailY = TEXT_AREA.y + TEXT_AREA.height - 3;
		int x = TEXT_AREA.x;
		if (complete)
		{
			shadow(g, "Complete! Roll your next goal.", x, detailY, DONE);
		}
		else if (tier != null)
		{
			g.drawImage(TierIcons.get(tier), x, detailY - 12, 14, 14, null);
			shadow(g, fit(g, tier.getDisplayName() + " · " + item.getPage(), TEXT_AREA.width - 18), x + 18, detailY, DETAIL);
		}
	}

	private static Rectangle frac(double x, double y, double w, double h)
	{
		return new Rectangle((int) (x * WIDTH), (int) (y * HEIGHT), (int) (w * WIDTH), (int) (h * HEIGHT));
	}

	private static String fit(Graphics2D g, String text, int width)
	{
		FontMetrics fm = g.getFontMetrics();
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String cut = text;
		while (cut.length() > 1 && fm.stringWidth(cut + "…") > width)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut + "…";
	}

	private static void centered(Graphics2D g, String text, Rectangle area, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		g.setColor(color);
		g.drawString(text, area.x + (area.width - fm.stringWidth(text)) / 2, area.y + (area.height + fm.getAscent()) / 2 - 1);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.orchardskydigital.clogslots.ui;

import com.orchardskydigital.clogslots.difficulty.Tier;
import com.orchardskydigital.clogslots.log.AccountSummary;
