import java.util.Map;
import lombok.Builder;
import lombok.Value;

/** Snapshot of everything the sidebar shows, built on the client thread. */
@Value
@Builder
public class PanelState
{
	boolean loggedIn;
	String playerName;
	boolean syncing;
	/** Items recorded by the plugin for this account. */
	int synced;
	/** Items the game says you have, or -1 if unknown. */
	int gameCount;
	AccountSummary summary;
	ClogItem goal;
	Tier goalTier;
	/** Best drop chance for the goal, or null if it only comes from shops/recipes. */
	Double goalChance;
	boolean goalComplete;
	Map<Tier, Integer> remainingByTier;
	/** The tier the next roll will come from, or null when nothing is left. */
	Tier rollingTier;

	/** What the header shows under the title. */
	public String accountLabel()
	{
		if (!loggedIn)
		{
			return "Not logged in";
		}
		return playerName != null ? playerName : "Loading account…";
	}

	public boolean hasSynced()
	{
		return synced > 0;
	}

	/** Items the game knows about that this plugin hasn't recorded yet. */
	public int behindBy()
	{
		return gameCount < 0 ? 0 : Math.max(0, gameCount - synced);
	}
}

package com.orchardskydigital.clogslots.ui;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import lombok.Getter;

/** The strip of items a reel scrolls through, ending on the rolled item, plus its ease-out timing. */
public class ReelSequence<T>
{
	@Getter
	private final List<T> items;

	private ReelSequence(List<T> items)
	{
		this.items = items;
	}

	public static <T> ReelSequence<T> build(List<T> pool, T target, int length, Random random)
	{
		List<T> items = new ArrayList<>(length);
		for (int i = 0; i < length - 1; i++)
		{
			items.add(pickFiller(pool, i == 0 ? null : items.get(i - 1), random));
		}
		// keep the item before the target different from it, so the stop is readable
		if (length > 1 && pool.size() > 1 && items.get(length - 2).equals(target))
		{
			items.set(length - 2, pickFiller(pool, target, random));
		}
		items.add(target);
		return new ReelSequence<>(items);
	}

	private static <T> T pickFiller(List<T> pool, T avoid, Random random)
	{
		if (pool.size() == 1)
		{
			return pool.get(0);
		}
		T pick;
		do
		{
			pick = pool.get(random.nextInt(pool.size()));
		}
		while (pick.equals(avoid));
		return pick;
	}

	/**
	 * Fractional index of the item centred in the window at spin progress {@code t} (0..1).
	 * Cubic ease-out: fast start, slow landing.
	 */
	public double positionAt(double t)
	{
		double clamped = Math.max(0, Math.min(1, t));
		double eased = 1 - Math.pow(1 - clamped, 3);
		return eased * (items.size() - 1);
	}
}

package com.orchardskydigital.clogslots.ui;

import com.orchardskydigital.clogslots.ClogSlotsConfig;
import com.orchardskydigital.clogslots.log.ClogItem;
import com.orchardskydigital.clogslots.roll.RolledGoal;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.Random;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/** Plays the slot machine spin for a rolled goal, then shows the result for a few seconds. */
@Singleton
public class SlotMachineOverlay extends Overlay
{
	private static final BufferedImage FRAME = BundledArt.load("slot-frame.png");
	private static final int FRAME_WIDTH = 300;
	private static final int FRAME_HEIGHT = 190;
	/** The transparent reel window inside slot-frame.png. */
	private static final Rectangle WINDOW = new Rectangle(41, 50, 217, 83);
	private static final int FOOTER_HEIGHT = 40;
	private static final int ROW_HEIGHT = 38;
	private static final int REEL_LENGTH = 40;
	private static final long RESULT_HOLD_MS = 6000;

	private static final Color REEL = new Color(0x15100b);
	private static final Color GOLD = new Color(0xc8a24a);
	private static final Color FOOTER = new Color(0, 0, 0, 170);
	private static final Color TEXT = new Color(0xff981f);

	private final ItemManager itemManager;
	private final ClogSlotsConfig config;

	private ReelSequence<ClogItem> reel;
	private RolledGoal goal;
	private long startMs;
	private long durationMs;
	private Runnable onLanded;
	private boolean landed;

	@Inject
	SlotMachineOverlay(ItemManager itemManager, ClogSlotsConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.HIGH);
		setMovable(true);
	}

	/** Starts a spin. {@code onLanded} runs once on the client thread when the reel stops. */
	public void spin(RolledGoal goal, long durationMs, Runnable onLanded)
	{
		this.goal = goal;
		this.reel = ReelSequence.build(goal.getTierCandidates(), goal.getItem(), REEL_LENGTH, new Random());
		this.durationMs = Math.max(500, durationMs);
		this.onLanded = onLanded;
		this.landed = false;
		this.startMs = System.currentTimeMillis();
	}

	public void hide()
	{
		goal = null;
		reel = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (reel == null)
		{
			return null;
		}
		long elapsed = System.currentTimeMillis() - startMs;
		double t = (double) elapsed / durationMs;
		if (t >= 1 && !landed)
		{
			landed = true;
			if (onLanded != null)
			{
				onLanded.run();
			}
		}
		if (elapsed > durationMs + RESULT_HOLD_MS)
		{
			hide();
			return null;
		}

		double scale = config.slotSize().getScale();
		Graphics2D scaled = (Graphics2D) g.create();
		scaled.scale(scale, scale);
		// nearest-neighbour keeps the pixel art and item sprites crisp when scaled up
		scaled.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		drawMachine(scaled, t);
		scaled.dispose();
		return new Dimension((int) Math.ceil(FRAME_WIDTH * scale), (int) Math.ceil((FRAME_HEIGHT + FOOTER_HEIGHT) * scale));
	}

	private void drawMachine(Graphics2D g, double t)
	{
		drawReel(g, reel.positionAt(t));
		g.drawImage(FRAME, 0, 0, FRAME_WIDTH, FRAME_HEIGHT, null);
		drawPayline(g);
		drawFooter(g, t >= 1);
	}

	private void drawReel(Graphics2D g, double position)
	{
		g.setColor(REEL);
		g.fill(WINDOW);

		Shape oldClip = g.getClip();
		g.clip(WINDOW);
		int base = (int) Math.floor(position);
		double frac = position - base;
		int centerY = centerRowY();
		for (int k = -2; k <= 2; k++)
		{
			int index = base + k;
			if (index < 0 || index >= reel.getItems().size())
			{
				continue;
			}
			// items scroll downward: higher index enters from the top
			int y = (int) Math.round(centerY - (k - frac) * ROW_HEIGHT);
			drawRow(g, reel.getItems().get(index), y);
		}
		g.setClip(oldClip);
	}

	private void drawRow(Graphics2D g, ClogItem item, int y)
	{
		BufferedImage icon = itemManager.getImage(item.getItemId());
		g.drawImage(icon, WINDOW.x + 8, y + (ROW_HEIGHT - icon.getHeight()) / 2, null);
		g.setFont(FontManager.getRunescapeFont());
		FontMetrics fm = g.getFontMetrics();
		shadowText(g, item.getName(), WINDOW.x + 52, y + ROW_HEIGHT / 2 + fm.getAscent() / 2 - 2, Color.WHITE);
	}

	private void drawPayline(Graphics2D g)
	{
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(1.5f));
		int y = centerRowY();
		g.drawLine(WINDOW.x, y, WINDOW.x + WINDOW.width, y);
		g.drawLine(WINDOW.x, y + ROW_HEIGHT, WINDOW.x + WINDOW.width, y + ROW_HEIGHT);
	}

	private void drawFooter(Graphics2D g, boolean stopped)
	{
		int top = FRAME_HEIGHT + 2;
		g.setColor(FOOTER);
		g.fillRoundRect(20, top, FRAME_WIDTH - 40, FOOTER_HEIGHT - 4, 10, 10);

		BufferedImage badge = TierIcons.get(goal.getTier());
		g.drawImage(badge, 26, top + 2, null);

		String text = stopped
			? goal.getTier().getDisplayName() + " tier - " + goal.getItem().getPage()
			: "Rolling " + goal.getTier().getDisplayName() + " tier...";
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		shadowText(g, text, 64, top + (FOOTER_HEIGHT - 4) / 2 + fm.getAscent() / 2 - 1, TEXT);
	}

	private static int centerRowY()
	{
		return WINDOW.y + (WINDOW.height - ROW_HEIGHT) / 2;
	}

	private static void shadowText(Graphics2D g, String text, int x, int baseline, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, baseline + 1);
		g.setColor(color);
		g.drawString(text, x, baseline);
	}
}

