	public static final Color SUCCESS = new Color(0x4ade80);
	public static final Color WARNING = new Color(0xfbbf24);

	public static final int RADIUS = 10;
	/** Inner padding of a card; clears the 12px frame art. */
	public static final int PAD = 15;
	public static final int GAP = 10;

	private static final String FAMILY = pickFamily("Inter", "Segoe UI", "Helvetica Neue", "Arial");

	private Theme()
	{
	}

	public static Font font(int style, float size)
	{
		return new Font(FAMILY, style, 1).deriveFont(style, size);
	}

	public static Font body()
	{
		return font(Font.PLAIN, 12f);
	}

	public static Font small()
	{
		return font(Font.PLAIN, 11f);
	}

	public static Font label()
	{
		return font(Font.BOLD, 10f);
	}

	public static Font title()
	{
		return font(Font.BOLD, 15f);
	}

	public static Color tierColor(Tier tier)
	{
		switch (tier)
		{
			case EASY:
				return new Color(0xd08a4a);
			case MEDIUM:
				return new Color(0xb4b4c0);
			case HARD:
				return new Color(0x6b8ff0);
			case ELITE:
				return new Color(0x4cc46a);
			default:
				return new Color(0xe25555);
		}
	}

	private static String pickFamily(String... preferred)
	{
		Set<String> installed = new HashSet<>(Arrays.asList(
			GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()));
		for (String family : preferred)
		{
			if (installed.contains(family))
			{
				return family;
			}
		}
		return Font.SANS_SERIF;
	}
}

