import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JButton;

/** A full-width button drawn from gold button art, with a hover state and a dimmed disabled state. */
public class ArtButton extends JButton
{
	private static final Color LABEL = new Color(0x2a1a08);
	private static final Color LABEL_HIGHLIGHT = new Color(255, 236, 170, 140);

	private final NinePatch normal;
	private final NinePatch hover;
	private boolean hovered;

	public ArtButton(NinePatch normal, NinePatch hover, int height)
	{
		this.normal = normal;
		this.hover = hover;
		setContentAreaFilled(false);
		setBorderPainted(false);
		setFocusPainted(false);
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setPreferredSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hovered = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hovered = false;
				repaint();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		if (!isEnabled())
		{
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
		}
		(hovered && isEnabled() ? hover : normal).draw(g2, 0, 0, getWidth(), getHeight());

		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setFont(getFont());
		FontMetrics fm = g2.getFontMetrics();
		int x = (getWidth() - fm.stringWidth(getText())) / 2;
		int y = (getHeight() - fm.getHeight()) / 2 + fm.getAscent();
		// engraved look: light highlight under dark lettering
		g2.setColor(LABEL_HIGHLIGHT);
		g2.drawString(getText(), x, y + 1);
		g2.setColor(LABEL);
		g2.drawString(getText(), x, y);
		g2.dispose();
	}
}

