package com.orchardskydigital.clogslots.ui.components;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Draws a framed image at any size: the four corners keep their size, the edges stretch along
 * one axis and the centre stretches both ways. Insets are in source pixels.
 */
public class NinePatch
{
	private final BufferedImage image;
	private final int left;
	private final int top;
	private final int right;
	private final int bottom;

	public NinePatch(BufferedImage image, int left, int top, int right, int bottom)
	{
		this.image = image;
		this.left = left;
		this.top = top;
		this.right = right;
		this.bottom = bottom;
	}

	public void draw(Graphics2D g, int x, int y, int w, int h)
	{
		draw(g, x, y, w, h, 1.0);
	}

	/** @param borderScale how many screen pixels each source border pixel takes */
	public void draw(Graphics2D g, int x, int y, int w, int h, double borderScale)
	{
		int sw = image.getWidth();
		int sh = image.getHeight();
		int dl = (int) Math.round(left * borderScale);
		int dt = (int) Math.round(top * borderScale);
		int dr = (int) Math.round(right * borderScale);
		int db = (int) Math.round(bottom * borderScale);

		int[] sx = {0, left, sw - right, sw};
		int[] sy = {0, top, sh - bottom, sh};
		int[] dx = {x, x + dl, x + w - dr, x + w};
		int[] dy = {y, y + dt, y + h - db, y + h};

		Object hint = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		for (int row = 0; row < 3; row++)
		{
			for (int col = 0; col < 3; col++)
			{
				if (dx[col + 1] > dx[col] && dy[row + 1] > dy[row])
				{
					g.drawImage(image,
						dx[col], dy[row], dx[col + 1], dy[row + 1],
						sx[col], sy[row], sx[col + 1], sy[row + 1], null);
				}
			}
		}
		if (hint != null)
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, hint);
		}
	}
}

