package com.orchardskydigital.clogslots.ui.components;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/** A thin rounded progress bar with no labels. */
public class SlimBar extends JComponent
{
	private final Color track;
	private final Color fill;
	private final double fraction;

	public SlimBar(int value, int max, int height, Color track, Color fill)
	{
		this.track = track;
		this.fill = fill;
		this.fraction = max <= 0 ? 0 : Math.min(1, (double) value / max);
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int h = getHeight();
		g2.setColor(track);
		g2.fillRoundRect(0, 0, getWidth(), h, h, h);
		int w = (int) Math.round(getWidth() * fraction);
		if (w > 0)
		{
			g2.setColor(fill);
			g2.fillRoundRect(0, 0, Math.max(w, h), h, h, h);
		}
		g2.dispose();
	}
}

