import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import javax.swing.JTextArea;

/**
 * Read-only paragraph that word-wraps at a fixed width. Swing can't wrap text inside a BoxLayout
 * without knowing the width up front, so callers pass the width they lay it out in.
 */
public class WrapText extends JTextArea
{
	private final int width;

	public WrapText(String text, Font font, Color color, int width)
	{
		super(text);
		this.width = width;
		setFont(font);
		setForeground(color);
		setLineWrap(true);
		setWrapStyleWord(true);
		setEditable(false);
		setFocusable(false);
		setOpaque(false);
		setBorder(null);
		setHighlighter(null);
		setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	@Override
	public Dimension getPreferredSize()
	{
		// sizing to the target width first makes the text area report its wrapped height
		setSize(width, Short.MAX_VALUE);
		return new Dimension(width, super.getPreferredSize().height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return getPreferredSize();
	}
}

