package com.orchardskydigital.clogslots.difficulty;

import com.google.gson.Gson;
import java.io.StringReader;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class DifficultyIndexTest
{
	private static DifficultyIndex index(Object... idChancePairs)
	{
		Map<Integer, Double> chances = new HashMap<>();
		for (int i = 0; i < idChancePairs.length; i += 2)
		{
			chances.put((Integer) idChancePairs[i], (Double) idChancePairs[i + 1]);
		}
		return new DifficultyIndex(chances);
	}

	@Test
	public void scoreIsNegativeLog10OfChance()
	{
		var index = index(1, 1.0 / 1000);
		assertEquals(3.0, index.scoreOf(1, Collections.singletonList(1)), 1e-9);
	}

	@Test
	public void guaranteedItemScoresZero()
	{
		var index = index(1, 1.0);
		assertEquals(0.0, index.scoreOf(1, Collections.singletonList(1)), 1e-9);
	}

	@Test
	public void unknownItemUsesMedianOfItsPage()
	{
		var index = index(1, 0.1, 2, 0.01, 3, 0.001);
		// page scores 1, 2, 3 -> median 2
		assertEquals(2.0, index.scoreOf(99, Arrays.asList(1, 2, 3, 99)), 1e-9);
	}

	@Test
	public void unknownItemOnUnknownPageUsesDefault()
	{
		var index = index();
		assertEquals(DifficultyIndex.DEFAULT_SCORE, index.scoreOf(99, Arrays.asList(98, 99)), 1e-9);
	}

	@Test
	public void tiersUseFixedThresholds()
	{
		assertEquals(Tier.EASY, Tier.forScore(0.0));
		assertEquals(Tier.EASY, Tier.forScore(0.99));
		assertEquals(Tier.MEDIUM, Tier.forScore(1.0));
		assertEquals(Tier.HARD, Tier.forScore(2.0));
		assertEquals(Tier.ELITE, Tier.forScore(2.7));
		assertEquals(Tier.MASTER, Tier.forScore(3.5));
		assertEquals(Tier.MASTER, Tier.forScore(9.0));
	}

	@Test
	public void loadsFromJson()
	{
		var index = DifficultyIndex.fromJson(new Gson(), new StringReader("{\"12922\": 0.001}"));
		assertEquals(3.0, index.scoreOf(12922, Collections.singletonList(12922)), 1e-9);
	}

	@Test
	public void chanceOfKnownAndUnknownItems()
	{
		var index = index(1, 0.25);
		assertEquals(0.25, index.chanceOf(1), 1e-9);
		org.junit.Assert.assertNull(index.chanceOf(2));
	}
}

package com.orchardskydigital.clogslots.difficulty;

import com.google.gson.Gson;
import java.io.StringReader;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class TierOverridesTest
{
	// item 1 auto EASY (always), item 2 auto MASTER (1/10,000)
	private static final List<Integer> PAGE = Arrays.asList(1, 2);

	private static DifficultyIndex index(String overridesJson)
	{
		var chances = new java.util.HashMap<Integer, Double>();
		chances.put(1, 1.0);
		chances.put(2, 1.0 / 10_000);
		return new DifficultyIndex(chances, TierOverrides.fromJson(new Gson(), new StringReader(overridesJson)));
	}

	@Test
	public void noOverridesUsesAutoTier()
	{
		assertEquals(Tier.EASY, index("{}").tierOf(1, "Tombs of Amascut", PAGE));
	}

	@Test
	public void pageOverrideBeatsAutoTier()
	{
		var index = index("{\"pages\": {\"Tombs of Amascut\": \"ELITE\"}}");
		assertEquals(Tier.ELITE, index.tierOf(1, "Tombs of Amascut", PAGE));
		assertEquals(Tier.ELITE, index.tierOf(2, "Tombs of Amascut", PAGE));
		assertEquals(Tier.EASY, index.tierOf(1, "Barrows Chests", PAGE));
	}

	@Test
	public void itemOverrideBeatsPageOverride()
	{
		var index = index("{\"pages\": {\"Tombs of Amascut\": \"ELITE\"}, \"items\": {\"2\": \"MASTER\"}}");
		assertEquals(Tier.MASTER, index.tierOf(2, "Tombs of Amascut", PAGE));
		assertEquals(Tier.ELITE, index.tierOf(1, "Tombs of Amascut", PAGE));
	}

	@Test
	public void itemOverrideAppliesOnAnyPage()
	{
		var index = index("{\"items\": {\"1\": \"HARD\"}}");
		assertEquals(Tier.HARD, index.tierOf(1, "Some other page", Collections.singletonList(1)));
	}

	@Test
	public void emptyOverridesHaveNoEntries()
	{
		assertEquals(0, TierOverrides.none().size());
	}
}

