package com.orchardskydigital.clogslots.log;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SyncTrackerTest
{
	@Test
	public void idleTrackerReportsNothing()
	{
		var tracker = new SyncTracker();
		assertFalse(tracker.onTick(10).isPresent());
	}

	@Test
	public void finishesTwoTicksAfterLastItem()
	{
		var tracker = new SyncTracker();
		tracker.start(100);
		tracker.onItem(100, true);
		tracker.onItem(101, false);
		assertFalse(tracker.onTick(102).isPresent());
		var result = tracker.onTick(103).get();
		assertEquals(2, result.getSeen());
		assertEquals(1, result.getAdded());
		assertFalse(tracker.isSyncing());
	}

	@Test
	public void timesOutWithNoItems()
	{
		var tracker = new SyncTracker();
		tracker.start(100);
		assertFalse(tracker.onTick(104).isPresent());
		var result = tracker.onTick(105).get();
		assertEquals(0, result.getSeen());
		assertTrue(result.isEmpty());
	}
}

package com.orchardskydigital.clogslots.roll;

import com.orchardskydigital.clogslots.difficulty.DifficultyIndex;
import com.orchardskydigital.clogslots.difficulty.Tier;
import com.orchardskydigital.clogslots.log.ClogItem;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoalRollerTest
{
	// ids 1-2 easy (1/2), 3-4 hard (1/200), 5 master (1/5000)
	private static final List<ClogItem> CATALOG = Arrays.asList(
		new ClogItem(1, "Easy A", "Page A", "Bosses"),
		new ClogItem(2, "Easy B", "Page B", "Other"),
		new ClogItem(3, "Hard A", "Page A", "Bosses"),
		new ClogItem(4, "Hard B", "Page C", "Raids"),
		new ClogItem(5, "Master", "Page C", "Raids"));

	private static GoalRoller roller()
	{
		Map<Integer, Double> chances = new HashMap<>();
		chances.put(1, 0.5);
		chances.put(2, 0.5);
		chances.put(3, 1.0 / 200);
		chances.put(4, 1.0 / 200);
		chances.put(5, 1.0 / 5000);
		return new GoalRoller(new DifficultyIndex(chances));
	}

	private static Set<Integer> ids(Integer... ids)
	{
		return new HashSet<>(Arrays.asList(ids));
	}

	@Test
	public void rollsOnlyFromEasiestRemainingTier()
	{
		var random = new Random(1);
		for (int i = 0; i < 50; i++)
		{
			var goal = roller().roll(CATALOG, ids(), Collections.emptySet(), random).get();
			assertEquals(Tier.EASY, goal.getTier());
		}
	}

	@Test
	public void movesUpATierWhenEasiestIsComplete()
	{
		var goal = roller().roll(CATALOG, ids(1, 2), Collections.emptySet(), new Random(1)).get();
		assertEquals(Tier.HARD, goal.getTier());
	}

	@Test
	public void neverRollsAnObtainedItem()
	{
		var random = new Random(7);
		for (int i = 0; i < 50; i++)
		{
			var goal = roller().roll(CATALOG, ids(1, 3), Collections.emptySet(), random).get();
			assertTrue(goal.getItem().getItemId() == 2);
		}
	}

	@Test
	public void excludedTabsAreSkipped()
	{
		var goal = roller().roll(CATALOG, ids(1), Collections.singleton("Other"), new Random(1)).get();
		assertEquals(Tier.HARD, goal.getTier());
	}

	@Test
	public void emptyWhenEverythingObtained()
	{
		assertFalse(roller().roll(CATALOG, ids(1, 2, 3, 4, 5), Collections.emptySet(), new Random(1)).isPresent());
	}

	@Test
	public void picksEveryCandidateInTierEventually()
	{
		var seen = new HashSet<Integer>();
		var random = new Random(3);
		for (int i = 0; i < 100; i++)
		{
			seen.add(roller().roll(CATALOG, ids(1, 2), Collections.emptySet(), random).get().getItem().getItemId());
		}
		assertEquals(ids(3, 4), seen);
	}

	@Test
	public void candidatesListsTheWholeTierForReelFiller()
	{
		var goal = roller().roll(CATALOG, ids(1, 2), Collections.emptySet(), new Random(1)).get();
		assertEquals(2, goal.getTierCandidates().size());
	}

	@Test
	public void pageOverrideMovesItemsOutOfEasiestTier()
	{
		Map<Integer, Double> chances = new HashMap<>();
		chances.put(1, 0.5);
		chances.put(2, 0.5);
		var overrides = com.orchardskydigital.clogslots.difficulty.TierOverrides.fromJson(new com.google.gson.Gson(),
			new java.io.StringReader("{\"pages\": {\"Page A\": \"ELITE\"}}"));
		var roller = new GoalRoller(new DifficultyIndex(chances, overrides));
		// item 1 (Page A) is now Elite, so only item 2 (Page B) is left in Easy
		for (int i = 0; i < 20; i++)
		{
			assertEquals(2, roller.roll(CATALOG, ids(3, 4, 5), Collections.emptySet(), new Random(i)).get().getItem().getItemId());
		}
	}
}

