package com.orchardskydigital.clogslots.ui;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ReelSequenceTest
{
	private static final List<String> POOL = Arrays.asList("a", "b", "c", "d");

	@Test
	public void landsOnTarget()
	{
		var reel = ReelSequence.build(POOL, "c", 30, new Random(1));
		assertEquals("c", reel.getItems().get(reel.getItems().size() - 1));
		assertEquals(30, reel.getItems().size());
	}

	@Test
	public void fillerComesFromPool()
	{
		var reel = ReelSequence.build(POOL, "c", 30, new Random(1));
		assertTrue(POOL.containsAll(reel.getItems()));
	}

	@Test
	public void singleCandidateStillSpins()
	{
		var reel = ReelSequence.build(Collections.singletonList("only"), "only", 10, new Random(1));
		assertEquals(10, reel.getItems().size());
	}

	@Test
	public void positionStartsAtZeroAndEndsOnLastItem()
	{
		var reel = ReelSequence.build(POOL, "c", 30, new Random(1));
		assertEquals(0.0, reel.positionAt(0.0), 1e-9);
		assertEquals(29.0, reel.positionAt(1.0), 1e-9);
		assertEquals(29.0, reel.positionAt(1.5), 1e-9);
	}

	@Test
	public void positionDeceleratesEaseOut()
	{
		var reel = ReelSequence.build(POOL, "c", 30, new Random(1));
		double firstHalf = reel.positionAt(0.5) - reel.positionAt(0.0);
		double secondHalf = reel.positionAt(1.0) - reel.positionAt(0.5);
		assertTrue(firstHalf > secondHalf * 2);
	}

	@Test
	public void avoidsSameItemTwiceInARowWhenPossible()
	{
		var items = ReelSequence.build(POOL, "c", 200, new Random(5)).getItems();
		for (int i = 1; i < items.size(); i++)
		{
			assertTrue(!items.get(i).equals(items.get(i - 1)));
		}
	}
}

package com.orchardskydigital.clogslots.ui.components;

import java.awt.image.BufferedImage;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class NinePatchTest
{
	private static final int CORNER = 0xffff0000;
	private static final int EDGE = 0xff00ff00;
	private static final int CENTER = 0xff0000ff;

	/** 10x10 source: 2px red corners, green edges, blue centre. */
	private static BufferedImage source()
	{
		var img = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < 10; y++)
		{
			for (int x = 0; x < 10; x++)
			{
				boolean edgeX = x < 2 || x >= 8;
				boolean edgeY = y < 2 || y >= 8;
				img.setRGB(x, y, edgeX && edgeY ? CORNER : edgeX || edgeY ? EDGE : CENTER);
			}
		}
		return img;
	}

	private static BufferedImage render(int w, int h)
	{
		var out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		var g = out.createGraphics();
		new NinePatch(source(), 2, 2, 2, 2).draw(g, 0, 0, w, h);
		g.dispose();
		return out;
	}

	@Test
	public void cornersStayFixedSizeWhenStretched()
	{
		var out = render(40, 30);
		assertEquals(CORNER, out.getRGB(0, 0));
		assertEquals(CORNER, out.getRGB(1, 1));
		assertEquals(CORNER, out.getRGB(39, 29));
		assertEquals(CORNER, out.getRGB(38, 0));
		assertEquals(EDGE, out.getRGB(2, 0));
	}

	@Test
	public void edgesAndCentreStretchToFill()
	{
		var out = render(40, 30);
		assertEquals(EDGE, out.getRGB(20, 0));
		assertEquals(EDGE, out.getRGB(0, 15));
		assertEquals(CENTER, out.getRGB(20, 15));
		assertEquals(CENTER, out.getRGB(37, 27));
	}

	@Test
	public void scaledInsetsGrowTheBorder()
	{
		var out = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		var g = out.createGraphics();
		new NinePatch(source(), 2, 2, 2, 2).draw(g, 0, 0, 40, 40, 2.0);
		g.dispose();
		assertEquals(CORNER, out.getRGB(3, 3));
		assertEquals(EDGE, out.getRGB(20, 3));
	}
}
